package id.apotek.lestari.ui

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asImageBitmap

// Logo Apotek Lestari (JPG 512px, latar putih) — disimpan sebagai Base64 karena
// push via GitHub API hanya mendukung file teks (file biner ditolak).
// Dipakai di header Beranda dan di struk/invoice.
private const val LOGO_BASE64 = ""

/** Decode logo sekali (di-cache per komposisi). Null kalau decode gagal. */
@Composable
fun rememberLogoBitmap(): ImageBitmap? {
    return remember {
        try {
            val bytes = Base64.decode(LOGO_BASE64, Base64.DEFAULT)
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
        } catch (_: Exception) {
            null
        }
    }
}
